SELECT *
FROM shopwizard.tOrdProdOptionChange

    AND ProdCode = #{pProdCode}
    AND ProdOption = #{pProdOption}
    AND ProdQty = #{pProdQty}

LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*)
FROM shopwizard.tOrdProdOptionChange

    AND ProdCode = #{pProdCode}
    AND ProdOption = #{pProdOption}
    AND ProdQty = #{pProdQty}
